import{_ as a,c as t,o,a3 as i}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/configuration/index.md","filePath":"master/sales/sales/configuration/index.md","lastUpdated":1793074831000}'),s={name:"master/sales/sales/configuration/index.md"};function r(n,e,l,c,u,d){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Configuration holds the one-time setup of the <strong>Sales</strong> module. <strong>Settings</strong> decide which features are available. <strong>Configurations</strong> hold the lists those features use, such as categories, packagings and tags.</p><blockquote><p><strong>In simple words:</strong> Settings switch features on. Configurations fill them with data.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open <code>Sales → Settings</code> to manage module-wide options.</p><ul><li><a href="./settings.html">Settings</a>: products, invoice policy, pricing, and quotation and order options.</li></ul><h2 id="configurations" tabindex="-1">Configurations <a class="header-anchor" href="#configurations" aria-label="Permalink to &quot;Configurations&quot;">​</a></h2><p>Open <code>Sales → Configurations</code> to manage these lists.</p><ul><li><a href="./product-categories.html">Product categories</a>: group products in a tree.</li><li><a href="./product-attributes.html">Product attributes</a>: define options such as size or colour for variants.</li><li><a href="./packagings.html">Packagings</a>: define pack sizes for a product.</li><li><a href="./tags.html">Tags</a>: colour labels for sales orders.</li><li><a href="./uom-categories.html">UOM categories</a>: units of measure and how they convert.</li></ul><p>Activity Plans and Activity Types appear in the same menu. They work the same way across Aureus, so they are covered in <a href="./../../../getting-started/activities.html">Activities</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Sales overview</a></li><li><a href="./../products-prices/manage-products.html">Manage products</a></li><li><a href="./../quotations-orders/create-quotation.html">Create a quotation</a></li></ul>',12)]))}const f=a(s,[["render",r]]);export{g as __pageData,f as default};
